                "deleteNodeSchemasFromSupabase: delete instance concepts failed",
            });
          }
          const { error: deleteInstanceContentError } = await supabaseClient
            .from("Content")
            .delete()
            .eq("space_id", spaceId)
            .in("source_local_id", instanceSourceLocalIds);
          if (deleteInstanceContentError) {
